import sys
sys.dont_write_bytecode=True
import additional_pfp_domain_remaining_audit as a
a.record('pfp/domain/aggregates/cycle_balance_aggregate.py',1,201,'Read full quartet aggregate. Constructor synchronizes cached digests and checks candidate/problem plus receipt candidate/verifier/problem bindings only when both ends exist; it omits verifier-to-problem binding there although bind_verifier checks it. is_verified copies receipt status and is_complete only checks four objects plus cached flag. submit_candidate and bind_verifier can replace objects without invalidating old receipt/verified state or rechecking all invariants. record_receipt checks available reference hashes but never receipt self-digest or mathematical witness. These lifecycle gaps warrant isolated controls; content binding is separate from actual native verification.',['cached verification stale','constructor binding omission','receipt status trust','invariant-preserving mutation gap'])
a.record('pfp/domain/entities/cycle_balance.py',1,350,'Read all four mutable domain entities and canonical dictionaries. Problem rechecks dimension/nilpotency/kernel membership but does not derive boundary matrices from carrier incidences or prove claimed nonexactness. Candidate validates identifiers/move then tuple-normalizes selected lists; preserves_chain_law serializes through bool coercion and witness entries are not strictly checked. Verifier checks rule nonemptiness/uniqueness but tuple contents/arithmetic domain remain annotation-dependent. Receipt trusts VERIFIED with null evidence, automatically computes absent digest but accepts a supplied digest without recomputation, and is mutable. Bind helpers compare freshly computed referenced entity digests, while aggregate caches can become stale. Serializer is sorted UTF8 json, not the RFC8785 claim in one docstring.',['matrix-carrier separation','untrusted candidate type gaps','mutable receipts','unchecked self-digest','digest profile wording'])
a.record('pfp/domain/value_objects/cycle_balance.py',1,218,'Read carrier/boundary/obstruction/hygiene value objects. Most lists are normalized to tuples, exact nonboolean integers checked, and bounds/edge IDs/endpoint references enforced. Vertices and faces need not be unique; face orientation stripping removes one minus here whereas wire carrier strips all, so conversion can refuse a wire-accepted repeated-minus reference. Matrix rectangularity is deferred to ProblemEntity; active obstruction stores metadata and supplied kernel witness but does not establish nonexactness. Three nonempty hygiene strings express claims rather than validating them.',['tuple normalization','wire/domain mismatch','carrier uniqueness gaps','nonexactness unproved','hygiene prose'])
a.record('pfp/domain/aggregates/base.py',1,21,'Read mutable aggregate base. Only a dataclass field tuple helper is supplied; invariant-preserving mutation described in prose is entirely a subclass responsibility. No automatic validation, transaction, digest or authority mechanism exists.',['aggregate responsibility','no automatic invariant enforcement'])
a.record('pfp/domain/entities/base.py',1,32,'Read entity base equality/hash by exact type and id. The id field is arbitrary/mutable. Dataclass subclasses using default eq generation can override this identity-only behavior and become unhashable; owner decorators must be checked rather than assuming the base docstring governs every entity. No uniqueness registry or immutability is implemented.',['identity contract','subclass dataclass behavior','mutable identity'])
a.record('pfp/domain/value_objects/base.py',1,35,'Read empty frozen value-object base and field-based equality/hash. Exact class comparison is intentional; immutability is shallow, validation is not implemented by the base, and hash uses Python hash rather than stable cryptographic/cross-process encoding. Subclasses must perform input validation and ensure their fields are hashable.',['nominal equality','shallow immutability','runtime hash ceiling'])
a.record('pfp/domain/value_objects/identifiers.py',1,273,'Read all nominal IDs, canonical checker names, SHA and normal-form regexes and optional Pydantic hooks. General IDs enforce exact string, whitespace/no-strip and length boundaries. Sha256Digest and NormalFormId use regex match with dollar anchor without a fullmatch/length/whitespace check, allowing a trailing newline despite exact canonical format claims; bounded probe pending. CheckerIdVO permits noncanonical IDs while is_canonical is only a property. Pydantic hooks call str_schema without strict=True before constructor; schema coercion may differ from direct construction. Imports of pydantic_core are deferred to hook invocation and were not invoked in probes.',['canonical token boundaries','regex end-anchor','checker membership separate','schema coercion'])
a.record('pfp/domain/value_objects/taxonomy.py',1,275,'Read declared task/mode/status/span/arithmetic/move/rule vocabularies and nominal validators. Exact strings must belong to the selected set. Task-family set can be extended by unvalidated global tokens/providers and providers execute when queried, so it is an injected mutable admission policy. Other status values are labels; is_accepted/is_verified do no replay or proof checking. No provider was registered or invoked during the audit.',['declared taxonomy','dynamic admission policy','status not evidence'])
a.record('pfp/domain/kernel/result.py',1,241,'Read all terminal/refusal labels, DomainError record, Result operations, collection helpers and verdict records. Error record differs from exceptions.DomainError and enforces no authority/type fields. Public Result constructor permits inconsistent value/error/tag combinations; factories produce conventional variants and combinators rely on typed callbacks without catching exceptions. EvaluationVerdict and GenesisCycleVerdict do no arithmetic/type/witness validation: ExactIntegerSmithNormalForm and LocalReplay are default strings, not checked evidence. Consumers must bind/recompute their claims.',['parallel error types','passive result constructor','callback trust','verdict data not proof'])
a.record('pfp/domain/value_objects/task_family_tokens.py',1,127,'Read the complete generated task-family vocabulary. It is a fixed frozenset of labels, including physics/quantum/mechanism categories; membership validates naming only, not any associated mathematical or physical claim. The stated source parity test is a dependency assertion not rerun here. Import has no I/O or provider call.',['generated vocabulary','labels not mathematical coverage'])
a.report()
